// Contract with the core (identical for every ERP):
//   in:  { operation: "price_check", payload: { customer_code, currency, lines: [{ line_number, sku, quantity, unit }] } }
//   out: { prices: [{ sku, unit_price, currency }] }  — net price per catalogue unit for this customer
// Everything below is specific to the client's ERP: request format, URL, authentication, mapping.
const command = $input.first().json;
if (command.operation !== "price_check") {
  throw new Error(`Unknown ERP connector operation: ${command.operation}`);
}
const payload = command.payload ?? {};
return [{
  json: {
    customer_code: payload.customer_code ?? null,
    lines: (payload.lines ?? []).map(line => ({ sku: line.sku, quantity: line.quantity, unit: line.unit })),
  },
}];

// ERP response -> connector contract. Adjust the field names to the client's ERP API.
// The core validates every price again (positive amount, currency, only requested SKUs).
const items = $input.first().json.items;
if (!Array.isArray(items)) {
  throw new Error("ERP response has no items list.");
}
return [{
  json: {
    prices: items.map(item => ({ sku: String(item.index), unit_price: item.net_price, currency: item.curr })),
  },
}];
